       [("Logistic growth", "Nt = Kc/(1 + (Kc - N0)/N0*exp(-r*tt))"), ("Time to target", "tf = log(fk*(Kc - N0)/(N0*(1 - fk)))/r"), ("Maximum rate", "rmax = r*Kc/4")], ["Nt", "tf", "rmax"], {"N0": "50 1/ha", "Kc": "1200 1/ha", "r": "0.35 1/yr", "tt": "10 yr", "fk": "90 %"},
